<?php $vendorSetupDb=get_db();$vendorSetupChecks=[];foreach(['store'=>['vendor_store_profiles','store.php','Store profile','fa-store',' AND description IS NOT NULL AND description<>"" AND support_email IS NOT NULL AND support_email<>""'],'address'=>['vendor_addresses','dispatch-address.php','Dispatch address','fa-location-dot',' AND address_type="dispatch"'],'delivery'=>['vendor_shipping_settings','delivery.php','Delivery setup','fa-truck-fast',''],'bank'=>['vendor_bank_accounts','payout-bank.php','Payout bank','fa-building-columns',' AND verification_status="verified"']] as $key=>$item){$statement=$vendorSetupDb->prepare('SELECT COUNT(*) FROM '.$item[0].' WHERE vendor_id=:id'.$item[4]);$statement->execute(['id'=>$vendorView['id']]);$ready=(int)$statement->fetchColumn()>0;$action=$ready?'Done':'Set up';if($key==='bank'&&!$ready){$pending=$vendorSetupDb->prepare('SELECT COUNT(*) FROM vendor_bank_accounts WHERE vendor_id=:id');$pending->execute(['id'=>$vendorView['id']]);if((int)$pending->fetchColumn()>0)$action='Reviewing';}$vendorSetupChecks[$key]=['ready'=>$ready,'href'=>$item[1],'label'=>$item[2],'icon'=>$item[3],'action'=>$action];} ?>
<section class="vc-page-actions vc-dashboard-hero"><div><span class="vc-dashboard-eyebrow">YOUR STORE TODAY</span><h2>Focus on what needs action.</h2><p>Review new orders, keep stock accurate, arrange delivery and track your money.</p><div class="vc-dashboard-status"><span class="vc-status info" id="vd-store-status">Loading your store</span> <span class="vc-status" id="vd-verification-status"></span></div></div><div class="vc-actions"><a class="vc-btn" href="/conscious/partner/catalog#add-product"><i class="fa-solid fa-plus"></i>Add product</a><a class="vc-btn primary" href="/conscious/partner/orders"><i class="fa-solid fa-bag-shopping"></i>Process orders</a></div></section>
<?php if(array_filter($vendorSetupChecks,static fn(array $check): bool=>!$check['ready'])): ?><section class="vc-card mt-3" aria-labelledby="vendor-after-approval"><div class="vc-card-head"><h2 id="vendor-after-approval">Finish setup when you are ready</h2></div><div class="vc-card-body vc-journey vc-setup-journey"><?php foreach($vendorSetupChecks as $key=>$check): ?><a href="/conscious/partner/<?= htmlspecialchars(pathinfo($check['href'],PATHINFO_FILENAME),ENT_QUOTES,'UTF-8') ?>"><span><i class="fa-solid <?= htmlspecialchars($check['icon'],ENT_QUOTES,'UTF-8') ?>" aria-hidden="true"></i></span><div><strong><?= htmlspecialchars($check['label'],ENT_QUOTES,'UTF-8') ?></strong><small><?= $key==='bank'?'Needed before payout':($key==='address'?'Used for fulfilment pickup':'Needed before your first product goes live') ?></small></div><b><?= htmlspecialchars($check['action'],ENT_QUOTES,'UTF-8') ?></b></a><?php endforeach; ?></div></section><?php endif; ?>
